import copy

from .query import search_docs, tags
from .store import JsonStore, identifier, integer


_EVENT_FIELDS = {"id", "version", "body", "tags", "deleted"}
_MAX_DOCUMENTS = 10_000


class DocumentIndex:
    def __init__(self, path):
        self.store = JsonStore(path)

    def apply_batch(self, tenant, batch_id, events):
        identifier(tenant)
        identifier(batch_id)
        if not isinstance(events, list) or len(events) > 1000:
            raise ValueError("events")

        # Validate before entering the transaction and retain a fully detached
        # receipt/update value.  In particular, tag ordering is left intact.
        detached_events = copy.deepcopy(events)
        seen = set()
        for event in detached_events:
            if not isinstance(event, dict) or set(event) != _EVENT_FIELDS:
                raise ValueError("event shape")
            identifier(event["id"])
            integer(event["version"], high=1_000_000)
            if not isinstance(event["body"], str) or len(event["body"]) > 10000:
                raise ValueError("body")
            tags(event["tags"])
            if type(event["deleted"]) is not bool:
                raise ValueError("deleted")
            if event["id"] in seen:
                raise ValueError("duplicate document")
            seen.add(event["id"])

        def action(data):
            state = data.setdefault(tenant, {"docs": {}, "batches": {}})

            if batch_id in state["batches"]:
                if state["batches"][batch_id] != detached_events:
                    raise ValueError("batch conflict")
                return False

            docs = state["docs"]
            # Compute all consequences on a local mapping.  JsonStore is itself
            # copy-on-write, and this extra level makes the all-events decision
            # explicit before installing either documents or the receipt.
            updated_docs = copy.deepcopy(docs)
            for event in detached_events:
                old = updated_docs.get(event["id"])
                if old is None or event["version"] > old["version"]:
                    updated_docs[event["id"]] = copy.deepcopy(event)
                elif event["version"] == old["version"]:
                    if event != old:
                        raise ValueError("version conflict")
                    # An identical event at the current version is a no-op.
                # Lower versions are deliberately ignored, but remain in the
                # immutable batch receipt.

            if len(updated_docs) > _MAX_DOCUMENTS:
                raise ValueError("too many documents")

            state["docs"] = updated_docs
            state["batches"][batch_id] = copy.deepcopy(detached_events)
            return True

        return self.store.transact(action)

    def set_policy(self, tenant, revision, blocked_tags):
        """Install a tenant's independently versioned compliance policy."""
        identifier(tenant)
        integer(revision, high=1_000_000)
        # Validation includes duplicate detection and is deliberately completed
        # before looking at the current revision, including for stale updates.
        tags(blocked_tags)
        normalized_tags = sorted(blocked_tags)

        def action(data):
            # Initializing the ordinary stage-0 containers keeps tenants created
            # by a policy fully compatible with later document ingestion.
            state = data.setdefault(tenant, {"docs": {}, "batches": {}})
            old = state.get("policy")

            if old is not None:
                if revision < old["revision"]:
                    return False
                if revision == old["revision"]:
                    if normalized_tags != old["blocked_tags"]:
                        raise ValueError("policy revision conflict")
                    return False

            state["policy"] = {
                "revision": revision,
                "blocked_tags": normalized_tags,
            }
            return True

        return self.store.transact(action)

    def get(self, tenant, doc_id):
        identifier(tenant)
        identifier(doc_id)
        event = self.store.data.get(tenant, {}).get("docs", {}).get(doc_id)
        return copy.deepcopy(event)

    def search(self, tenant, query, limit=10, required_tags=None):
        identifier(tenant)
        state = self.store.data.get(tenant, {})
        policy = state.get("policy")
        blocked = () if policy is None else policy["blocked_tags"]
        return search_docs(state.get("docs", {}), query, limit, required_tags, blocked)

