from collections import Counter
import copy

from .store import identifier, integer


def tags(value):
    """Validate and return a tag list without changing its order."""
    if not isinstance(value, list):
        raise ValueError("tags list")
    for tag in value:
        identifier(tag)
    if len(set(value)) != len(value):
        raise ValueError("duplicate tag")
    return value


def search_docs(docs, query, limit, required_tags, blocked_tags=()):
    if not isinstance(query, str) or len(query) > 10000:
        raise ValueError("query")
    integer(limit, high=1000)

    required = set(tags([] if required_tags is None else required_tags))
    tokens = set(query.casefold().split())
    blocked = set(blocked_tags)
    ranked = []

    for event in docs.values():
        if event["deleted"]:
            continue
        event_tags = set(event["tags"])
        if blocked.intersection(event_tags):
            continue
        if not required.issubset(event_tags):
            continue

        words = Counter(event["body"].casefold().split())
        if not tokens.issubset(words):
            continue
        score = sum(words[token] for token in tokens)
        ranked.append((-score, event["id"], event))

    ranked.sort(key=lambda item: item[:2])
    return copy.deepcopy([item[2] for item in ranked[:limit]])

