import copy
import json
from pathlib import Path


class JsonStore:
    """A small copy-on-write JSON store.

    Mutations are applied to a detached candidate so an exception from the
    transaction cannot alter the in-memory state.  The candidate only becomes
    visible after its complete representation has been atomically installed.
    """

    def __init__(self, path):
        self.path = Path(path)
        self.data = json.loads(self.path.read_text(encoding="utf-8")) if self.path.exists() else {}

    def transact(self, action):
        candidate = copy.deepcopy(self.data)
        result = action(candidate)

        self.path.parent.mkdir(parents=True, exist_ok=True)
        temp = self.path.with_name(self.path.name + ".tmp")
        try:
            # ensure_ascii also permits every Python string accepted by the
            # public validators to be represented in a UTF-8 text file.
            payload = json.dumps(candidate, ensure_ascii=True, separators=(",", ":"))
            temp.write_text(payload, encoding="utf-8")
            temp.replace(self.path)
        except Exception:
            try:
                temp.unlink()
            except FileNotFoundError:
                pass
            raise

        self.data = candidate
        return copy.deepcopy(result)


def identifier(value):
    if not isinstance(value, str) or not value or len(value) > 128:
        raise ValueError("invalid identifier")
    return value


def integer(value, low=0, high=1_000_000_000):
    # bool is an int subclass, but is not an integer for this API.
    if type(value) is not int or not low <= value <= high:
        raise ValueError("invalid integer")
    return value

